(function(root){
const current=op=>Math.round((op.throttle-op.brake)*100);
function init(op){Object.assign(op,{systemsEnabled:true,doorsLocked:true,doorFault:false,deadman:true,deadmanAssisted:true,inverter:1,activeCab:'A',needsCabChange:false,assisted:false,pendingSignal:false,signalTarget:null,reverseAuthorized:false,reverseOrigin:null});}
function hold(engine,held){const op=engine.operator;if(!op?.systemsEnabled)return;if(op.easyMode&&!held){op.easyTargetSpeed=0;op.throttle=0;op.brake=1;op.message='Freno de servicio al salir de la ventana. Pulsa Acelerar para continuar.';return;}op.deadman=held;const t=engine.trains.find(t=>t.id===op.trainId);if(!held&&t.speed>.08){engine.emergency=true;op.throttle=0;op.brake=1;op.message='Hombre muerto liberado: frenado de emergencia.';}}
function emergency(engine){const op=engine.operator,t=engine.trains.find(t=>t.id===op?.trainId);if(engine.emergency){if(t?.speed>.08||!op?.deadman){if(op)op.message='Para rearmar: tren detenido y hombre muerto mantenido.';return false;}engine.emergency=false;}else engine.emergency=true;if(op){op.throttle=0;op.brake=1;op.easyTargetSpeed=0;op.assisted=false;op.message=engine.emergency?'Emergencia aplicada.':'Emergencia rearmada; freno mantenido.';}return true;}
function invert(engine,value){const op=engine.operator,t=engine.trains.find(t=>t.id===op?.trainId);if(!op)return false;if(t.speed>.08||op.throttle>0||op.phase!=='closed'){op.message='Inversor: detén el tren, lleva el mando a neutro o freno y cierra las puertas.';return false;}if(value===-1&&!op.reverseAuthorized){op.message='Solicita autorización PCC simulada para la maniobra.';return false;}op.inverter=value;op.assisted=false;op.message=value===-1?'Maniobra autorizada: máximo 5 km/h y 15 m en este ejercicio.':value===0?'Inversor neutro.':'Marcha adelante.';return true;}
function authorize(engine){const op=engine.operator,t=engine.trains.find(t=>t.id===op?.trainId);if(!op)return;if(t.speed>.08||op.phase!=='closed'||root.MetroManual.nearestStation(engine,t).distance>20){op.message='PCC simulado: detén el tren cerca de una parada, con puertas cerradas.';return;}op.reverseAuthorized=true;op.reverseOrigin=t.position;op.message='PCC simulado autoriza maniobra de hasta 15 m a 5 km/h. Selecciona reversa.';}
function changeCab(engine){const op=engine.operator,t=engine.trains.find(t=>t.id===op?.trainId);if(!op)return false;if(!op.needsCabChange||t.speed>.08||op.phase!=='closed'||op.inverter!==0){op.message='Cambio de cabina: terminal, detenido, puertas cerradas e inversor neutro.';return false;}op.activeCab=op.activeCab==='A'?'B':'A';t.direction*=-1;t.target+=t.direction;op.needsCabChange=false;op.inverter=1;op.brake=1;op.throttle=0;op.signalTarget=null;op.message='Cabina '+op.activeCab+' activa. Retorno esquemático; agujas y recorrido a pie no modelados.';return true;}
function beforeStep(engine,t,dt){const op=engine.operator;if(!op?.systemsEnabled)return;if(op.easyMode){stepEasy(engine,t);return;}const remaining=Math.abs(engine.lines[t.line].distances[t.target]-t.position),limit=(op.inverter===-1?5:engine.speedLimit(t))/3.6;if(!op.deadman){if(t.speed>.08)hold(engine,false);op.throttle=0;op.brake=1;}if(op.inverter===0||op.needsCabChange){op.throttle=0;op.brake=1;}if(op.inverter===-1&&op.reverseAuthorized){const left=15-Math.abs(t.position-op.reverseOrigin);if(left<=t.speed*t.speed/(2*(t.line===1?1.8:1.2))+.5){op.throttle=0;op.brake=1;if(t.speed<.08){op.reverseAuthorized=false;op.message='Maniobra completada; autorización revocada.';}}}if(op.inverter===-1&&(!op.reverseAuthorized||Math.abs(t.position-op.reverseOrigin)>=15)){op.throttle=0;op.brake=1;op.reverseAuthorized=false;op.message='Fin de autorización de maniobra; freno aplicado.';}
if(op.phase==='closed'&&op.inverter===1&&remaining<300&&t.speed>.08&&op.signalTarget!==t.target){op.pendingSignal=true;op.signalTarget=t.target;op.signalTime=0;}
if(op.pendingSignal)op.signalTime+=dt;
if(op.assisted&&op.deadman&&!engine.emergency&&op.inverter===1&&!op.needsCabChange&&op.phase==='closed'){const desired=Math.min(limit,Math.sqrt(2*(t.line===1?1.5:1)*Math.max(0,remaining-2)));const error=desired-t.speed;op.throttle=error>.3?Math.min(1,error/3):0;op.brake=error<-.02?1:0;if(remaining<=2.5&&t.speed<.15){op.throttle=0;op.brake=1;}}
if(op.pendingSignal&&op.signalTime>10&&!op.deadmanAssisted){op.throttle=0;op.brake=1;op.message='Aviso de aproximación sin reconocer: freno de servicio didáctico.';}if(t.speed>limit){op.throttle=0;op.brake=1;}
}
function stepEasy(engine,t){const op=engine.operator;op.deadman=true;op.deadmanAssisted=true;op.pendingSignal=false;
if(engine.emergency||!engine.power[t.line]||op.phase!=='closed'||op.needsCabChange||op.inverter!==1){op.throttle=0;op.brake=1;return;}
// Direct controls preserve the driver's traction/brake request on every frame.
if(op.assisted){const remaining=Math.max(0,t.direction*(engine.lines[t.line].distances[t.target]-t.position)),limit=engine.speedLimit(t)/3.6,desired=Math.min(limit,Math.sqrt(2*(t.line===1?1.5:1)*Math.max(0,remaining-2))),error=desired-t.speed;op.throttle=error>.3?Math.min(1,error/3):0;op.brake=error<-.02?1:0;if(remaining<=2.5&&t.speed<.15){op.throttle=0;op.brake=1;op.assisted=false;}}
}
function easyCommand(engine,value){const op=engine.operator;if(!op)return false;value=Math.max(0,Math.min(100,Math.round(Number(value)||0)));
if(engine.emergency||!engine.power[engine.trains.find(t=>t.id===op.trainId).line]||op.phase!=='closed'||op.needsCabChange){op.message=engine.emergency?'Tren en emergencia: detén y pulsa Rearmar emergencia.':op.needsCabChange?'Terminal: pulsa Cambiar cabina antes de salir.':op.phase!=='closed'?'Completa el cierre de puertas antes de dar tracción.':'Restablece la alimentación de tracción.';return false;}
op.easyTargetSpeed=0;op.assisted=false;op.deadman=true;op.throttle=value/100;op.brake=0;op.message=value?'Tracción aplicada: '+value+' %.':'Neutro: marcha por inercia.';return true;}
root.MetroCab={init,hold,emergency,invert,authorize,changeCab,beforeStep,current,easyCommand};
})(typeof window!=='undefined'?window:globalThis);
